permission_denials.command:
python3 -c "
import json,re,sys
p='journals/2026-08-19-routine-handover-check.md'
t=open(p).read()
assert t.startswith('---')
fm=t.split('---',2)[1]
try:
    import yaml
except ImportError:
    print('pyyaml missing'); sys.exit(9)
d=yaml.safe_load(fm)
sch=json.load(open('.claude/skills/investigate/journal.schema.json'))
req=sch['required']
print('missing top-level:',[k for k in req if k not in d])
print('unknown top-level:',[k for k in d if k not in sch['properties']])
print('verdict:',d['verdict'],'| root_cause present:','root_cause' in d)
ids={e['id'] for e in d['evidence']}
print('evidence ids:',len(ids))
bad=[]
for h in d['hypotheses']:
    refs=h['evidence_for']+h['evidence_against']
    if not refs: bad.append((h['id'],'no citations'))
    for r in refs:
        if r not in ids: bad.append((h['id'],'dangling '+r))
for lf in d.get('latent_findings',[]):
    for r in lf['evidence']:
        if r not in ids: bad.append(('latent','dangling '+r))
print('referential problems:',bad or 'none')
unused=ids-{r for h in d['hypotheses'] for r in h['evidence_for']+h['evidence_against']}-{r for lf in d.get('latent_findings',[]) for r in lf['evidence']}
print('evidence not cited by any hypothesis/latent:',sorted(unused, key=lambda x:int(x[1:])))
for e in d['evidence']:
    assert re.match(r'^E[1-9][0-9]*\$',e['id']), e['id']
    assert e['type'] in ('log','metric','probe'), e
print('states:',[(h['id'],h['state']) for h in d['hypotheses']])
print('wall_clock:',d['usage']['wall_clock_seconds'])
"
